import numpy as np
W1 = W['W1']
def idx(r,c,ch): return (r*10+c)*5+ch

norm_mat = {}
for ch in [0,1,2,3,4]:
    M = np.zeros((8,8))
    for i,r in enumerate(range(1,9)):
        for j,c in enumerate(range(1,9)):
            M[i,j] = np.linalg.norm(W1[idx(r,c,ch)])
    norm_mat[ch] = M

def corr(a,b):
    a = a.ravel().astype(float); b = b.ravel().astype(float)
    a = a - a.mean(); b = b - b.mean()
    return float(np.dot(a,b) / (np.linalg.norm(a)*np.linalg.norm(b) + 1e-12))

print("Spatial correlations of W1 row norms across 8x8 interior:")
for ch1,ch2 in [(2,1),(2,0),(2,4),(1,4),(1,0)]:
    print("  ch%d vs ch%d: r=%.3f" % (ch1,ch2,corr(norm_mat[ch1], norm_mat[ch2])))
print("Reward row means:", np.round(norm_mat[2].mean(axis=1),2))
print("Moving row means:", np.round(norm_mat[1].mean(axis=1),2))
print("Agent row means:", np.round(norm_mat[0].mean(axis=1),2))
